import { tags } from "typia";

/**
 * Generic analytics date range model used by multiple analytics request DTOs.
 *
 * This type expresses a closed or half-open time interval by specifying
 * inclusive start and end timestamps. Analytics queries use this range to bound
 * the time window for fact records such as subscriptions or inventory
 * adjustments.
 *
 * When either `from` or `to` is omitted, the analytics engine infers an
 * open-ended bound according to product defaults, for example infinite past or
 * present time.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IAnalyticsDateRange = {
  /**
   * Inclusive lower bound of the analytics time window.
   *
   * Represents the earliest timestamp (in ISO 8601 date-time format) that
   * should be considered when selecting underlying fact rows.
   *
   * If omitted, the backend may apply a default minimum such as a fixed
   * platform start date or relative interval (e.g., 90 days ago).
   */
  from?: (string & tags.Format<"date-time">) | undefined;

  /**
   * Inclusive upper bound of the analytics time window.
   *
   * Represents the latest timestamp (in ISO 8601 date-time format) that
   * should be included when filtering underlying fact rows.
   *
   * If omitted, the backend typically interprets this as "up to now" at query
   * execution time.
   */
  to?: (string & tags.Format<"date-time">) | undefined;
};
